REF_WIDTH = 85.0

def get_onepiece_geometries(target_width: float = 85.0, ring_position: str = "left"):
    """
    Restituisce le geometrie Shapely per i 4 tool della Snapmaker U1 + Base sagomata:
    1. base: Sagoma nera di supporto con asola portachiavi (Nero #1A1A1A, Tool 0)
    2. blue: Lettere O, N, E, P, E, C, E, ancoretta, sagoma Luffy e barre orizzontali (Blu #0080FF, Tool 1)
    3. white: Teschio, denti e 4 estremita tibie incrociate (Bianco #FFFFFF, Tool 2)
    4. yellow: Cappello di paglia + Corda (Giallo #FFCB05, Tool 3)
    5. black: Dettagli interni, orbite teschio, nastro cappello (Nero #1A1A1A, Tool 0)
    """
    scale = (target_width / REF_WIDTH) if target_width else 1.0

    g_blue = wkt.loads(WKT_ONEPIECE_BLUE)
    g_white = wkt.loads(WKT_ONEPIECE_WHITE)
    g_yellow = wkt.loads(WKT_ONEPIECE_YELLOW)
    g_black = wkt.loads(WKT_ONEPIECE_BLACK)
    g_base = wkt.loads(WKT_ONEPIECE_BASE_RAW)

    if abs(scale - 1.0) > 1e-4:
        g_blue = affinity.scale(g_blue, xfact=scale, yfact=scale, origin=(0, 0))
        g_white = affinity.scale(g_white, xfact=scale, yfact=scale, origin=(0, 0))
        g_yellow = affinity.scale(g_yellow, xfact=scale, yfact=scale, origin=(0, 0))
        g_black = affinity.scale(g_black, xfact=scale, yfact=scale, origin=(0, 0))
        g_base = affinity.scale(g_base, xfact=scale, yfact=scale, origin=(0, 0))

    # Allineamento asola portachiavi
    b_minx, b_miny, b_maxx, b_maxy = g_base.bounds
    center_y = (b_miny + b_maxy) / 2.0
    center_x = (b_minx + b_maxx) / 2.0

    r_outer = 4.25 * scale
    r_inner = 2.1 * scale

    ring_pos = str(ring_position).lower().strip()
    if ring_pos == "left":
        c_ring = Point(b_minx - 1.5 * scale, center_y)
        ring_poly = c_ring.buffer(r_outer)
        ring_hole = c_ring.buffer(r_inner)
        g_base = unary_union([g_base, ring_poly]).difference(ring_hole)
        g_blue = g_blue.difference(ring_hole)
    elif ring_pos == "top":
        c_ring = Point(center_x, b_maxy + 1.5 * scale)
        ring_poly = c_ring.buffer(r_outer)
        ring_hole = c_ring.buffer(r_inner)
        g_base = unary_union([g_base, ring_poly]).difference(ring_hole)
    elif ring_pos == "right":
        c_ring = Point(b_maxx + 1.5 * scale, center_y)
        ring_poly = c_ring.buffer(r_outer)
        ring_hole = c_ring.buffer(r_inner)
        g_base = unary_union([g_base, ring_poly]).difference(ring_hole)

    return {
        "base": g_base,
        "blue": g_blue,
        "white": g_white,
        "yellow": g_yellow,
        "black": g_black
    }
